#include "w5500_spi.h"

/* External SPI handle generated by CubeMX */
extern SPI_HandleTypeDef hspi1;

/* -------------------------------------------------------------------------- */
/* Low-Level Hardware Interface                                               */
/* -------------------------------------------------------------------------- */

void W5500_HardwareReset(void) {
#if defined(W5500_RST_GPIO_Port) && defined(W5500_RST_Pin)
    HAL_GPIO_WritePin(W5500_RST_GPIO_Port, W5500_RST_Pin, GPIO_PIN_RESET);
    HAL_Delay(10);
    HAL_GPIO_WritePin(W5500_RST_GPIO_Port, W5500_RST_Pin, GPIO_PIN_SET);
    HAL_Delay(50);
#else
    // Software reset via PHY control if no HW reset pin mapped
    wizchip_sw_reset();
#endif
}

void W5500_Select(void) {
    HAL_GPIO_WritePin(W5500_CS_GPIO_Port, W5500_CS_Pin, GPIO_PIN_RESET);
}

void W5500_Unselect(void) {
    HAL_GPIO_WritePin(W5500_CS_GPIO_Port, W5500_CS_Pin, GPIO_PIN_SET);
}

uint8_t W5500_ReadByte(void) {
    uint8_t rx_data = 0;
    uint8_t tx_data = 0xFF; // Dummy byte to generate SPI clock
    HAL_SPI_TransmitReceive(&hspi1, &tx_data, &rx_data, 1, HAL_MAX_DELAY);
    return rx_data;
}

void W5500_WriteByte(uint8_t byte) {
    HAL_SPI_Transmit(&hspi1, &byte, 1, HAL_MAX_DELAY);
}

void W5500_ReadBurst(uint8_t *pBuf, uint16_t len) {
    HAL_SPI_Receive(&hspi1, pBuf, len, HAL_MAX_DELAY);
}

void W5500_WriteBurst(uint8_t *pBuf, uint16_t len) {
    HAL_SPI_Transmit(&hspi1, pBuf, len, HAL_MAX_DELAY);
}

/* -------------------------------------------------------------------------- */
/* High-Level Driver Initialization                                           */
/* -------------------------------------------------------------------------- */

int8_t W5500_Init(wiz_NetInfo *netInfo) {
    // 1. Assert chip select low initially, unselect before reset
    W5500_Unselect();

    // 2. Pulse Reset Pin
    W5500_HardwareReset();

    // 3. Register Low-Level Callbacks with WIZnet Driver
    reg_wizchip_cs_cbfunc(W5500_Select, W5500_Unselect);
    reg_wizchip_spi_cbfunc(W5500_ReadByte, W5500_WriteByte);
    reg_wizchip_spiburst_cbfunc(W5500_ReadBurst, W5500_WriteBurst);

    // 4. Memory Partitioning: 2KB Rx and Tx memory allocated to all 8 sockets
    uint8_t rx_tx_buf_sizes[2][8] = {
        {2, 2, 2, 2, 2, 2, 2, 2}, // Rx buffers in KB
        {2, 2, 2, 2, 2, 2, 2, 2}  // Tx buffers in KB
    };

    if (ctlwizchip(CW_INIT_WIZCHIP, (void*)rx_tx_buf_sizes) == -1) {
        return -1; // Initialization failed
    }

    // 5. Apply Network Configuration (MAC, IP, Subnet, Gateway, DHCP Mode)
    if (netInfo != NULL) {
        wizchip_setnetinfo(netInfo);
    }

    return 0; // Success
}
